67	// Config holds the configuration for a search request.
68	type Config struct {
69		ServiceURL  string // Base URL of the search service
70		GitHubToken string
71		Owner       string
72		Repo        string
73		Repos       []string
74		Query       string
75		Limit       int
76		Author      string // Filter by author name
77		Date        string // Filter by time period: "week" or "month"
78		Branch      string // Filter by branch name
79		Page        int    // 1-based page number (0 means omit, API defaults to 1)
80	}
81	
82	// HasFilters reports whether any filter fields are set on the config.
83	func (c Config) HasFilters() bool {
84		return c.Author != "" || c.Date != "" || c.Branch != "" || len(c.Repos) > 0
85	}
86	
87	// ParsedInput holds the parsed query and optional filters extracted from search input.
88	type ParsedInput struct {
89		Query  string
90		Author string
91		Date   string
92		Branch string
93		Repos  []string
94	}
95	
96	// ParseSearchInput extracts filter prefixes from raw input.
97	// Supports quoted values for single-value filters, for example: author:"alice smith".
98	// Remaining tokens become the query.
99	func ParseSearchInput(raw string) ParsedInput {
100		var p ParsedInput
101		var queryParts []string
102	
103		tokens := tokenizeInput(raw)
104		for _, tok := range tokens {
105			switch {
106			case strings.HasPrefix(tok, "author:"):
107				p.Author = strings.Trim(tok[len("author:"):], "\"")
108			case strings.HasPrefix(tok, "date:"):
109				p.Date = strings.Trim(tok[len("date:"):], "\"")
110			case strings.HasPrefix(tok, "branch:"):
111				p.Branch = strings.Trim(tok[len("branch:"):], "\"")
112			case strings.HasPrefix(tok, "repo:"):
113				p.Repos = appendUnique(p.Repos, parseListFilter(strings.TrimPrefix(tok, "repo:"))...)
114			default:
115				queryParts = append(queryParts, tok)
116			}
117		}
118	
119		p.Query = strings.Join(queryParts, " ")
120		return p
121	}
122	
123	// tokenizeInput splits input on whitespace but respects quoted values after filter prefixes.
124	// Example: `author:"alice smith" fix bug` → ["author:\"alice smith\"", "fix", "bug"]
125	func tokenizeInput(s string) []string {
126		var tokens []string
127		i := 0
128		s = strings.TrimSpace(s)
129		for i < len(s) {
130			// Skip whitespace
131			for i < len(s) && s[i] == ' ' {
132				i++
133			}
134			if i >= len(s) {
135				break
136			}
137	
138			start := i
139	
140			// Look ahead: is this a prefix:"quoted" token?
141			if colonIdx := strings.Index(s[i:], ":\""); colonIdx >= 0 && !strings.Contains(s[i:i+colonIdx], " ") {
142				// Found prefix:" — scan to closing quote
143				quoteStart := i + colonIdx + 2
144				endQuote := strings.IndexByte(s[quoteStart:], '"')
145				if endQuote >= 0 {
146					i = quoteStart + endQuote + 1
147					tokens = append(tokens, s[start:i])
148					continue
149				}
150			}
151	
152			// Regular token: advance to next space
153			for i < len(s) && s[i] != ' ' {
154				i++
155			}
156			tokens = append(tokens, s[start:i])
157		}
158		return tokens
159	}
