179	// ValidateRepoFilters ensures repo filters match backend semantics.
180	func ValidateRepoFilters(repos []string) error {
181		if len(repos) > 1 {
182			return errors.New("only one explicit repo filter is currently supported")
183		}
184		if len(repos) == 1 && !isValidRepoFilter(repos[0]) {
185			return fmt.Errorf(
186				"invalid repo filter %q: expected owner/name or *; if you meant all repos, quote the asterisk: --repo '*'",
187				repos[0],
188			)
189		}
190		return nil
191	}
192	
193	func isValidRepoFilter(repo string) bool {
194		if repo == AllReposFilter {
195			return true
196		}
197		if strings.Contains(repo, " ") {
198			return false
199		}
200		parts := strings.Split(repo, "/")
201		return len(parts) == 2 && parts[0] != "" && parts[1] != ""
202	}
203	
204	func appendUnique(existing []string, values ...string) []string {
205		if len(values) == 0 {
206			return existing
207		}
208	
209		seen := make(map[string]struct{}, len(existing)+len(values))
210		for _, value := range existing {
211			seen[value] = struct{}{}
212		}
213		for _, value := range values {
214			if _, ok := seen[value]; ok {
215				continue
216			}
217			seen[value] = struct{}{}
218			existing = append(existing, value)
219		}
220	
221		return existing
222	}
