224	var httpClient = &http.Client{}
225	
226	// Search calls the search service to perform a hybrid search.
227	func Search(ctx context.Context, cfg Config) (*Response, error) {
228		ctx, cancel := context.WithTimeout(ctx, apiTimeout)
229		defer cancel()
230	
231		serviceURL := cfg.ServiceURL
232		if serviceURL == "" {
233			serviceURL = DefaultServiceURL
234		}
235	
236		u, err := url.Parse(serviceURL)
237		if err != nil {
238			return nil, fmt.Errorf("parsing service URL: %w", err)
239		}
240		u.Path = "/search/v1/search"
241	
242		q := u.Query()
243		q.Set("q", cfg.Query)
244		if err := ValidateRepoFilters(cfg.Repos); err != nil {
245			return nil, err
246		}
247		allRepos := len(cfg.Repos) == 1 && cfg.Repos[0] == AllReposFilter
248		if len(cfg.Repos) > 0 && !allRepos {
249			for _, repo := range cfg.Repos {
250				q.Add("repo", repo)
251			}
252		} else if len(cfg.Repos) == 0 && cfg.Owner != "" && cfg.Repo != "" {
253			q.Set("repo", cfg.Owner+"/"+cfg.Repo)
254		}
255		q.Set("types", "checkpoints")
256		if cfg.Limit > 0 {
257			q.Set("limit", strconv.Itoa(cfg.Limit))
258		}
259		if cfg.Author != "" {
260			q.Set("author", cfg.Author)
261		}
262		if cfg.Date != "" {
263			q.Set("date", cfg.Date)
264		}
265		if cfg.Branch != "" {
266			q.Set("branch", cfg.Branch)
267		}
268		if cfg.Page > 0 {
269			q.Set("page", strconv.Itoa(cfg.Page))
270		}
271		u.RawQuery = q.Encode()
272	
273		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
274		if err != nil {
275			return nil, fmt.Errorf("creating request: %w", err)
276		}
277		req.Header.Set("Authorization", "Bearer "+cfg.GitHubToken)
278		req.Header.Set("User-Agent", "entire-cli")
279	
280		resp, err := httpClient.Do(req)
281		if err != nil {
282			return nil, fmt.Errorf("calling search service: %w", err)
283		}
284		defer resp.Body.Close()
285	
286		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
287		if err != nil {
288			return nil, fmt.Errorf("reading response: %w", err)
289		}
290	
291		if resp.StatusCode != http.StatusOK {
292			var errResp struct {
293				Error string `json:"error"`
294			}
295			if json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
296				return nil, fmt.Errorf("search service error (%d): %s", resp.StatusCode, errResp.Error)
297			}
298			return nil, fmt.Errorf("search service returned %d: %s", resp.StatusCode, string(body))
299		}
300	
301		var result Response
302		if err := json.Unmarshal(body, &result); err != nil {
303			return nil, fmt.Errorf("unexpected response from search service: %s", string(body))
304		}
305	
306		if result.Error != "" {
307			return nil, fmt.Errorf("search service error: %s", result.Error)
308		}
309	
310		return &result, nil
311	}
